<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRouter} from 'vue-router'
import {NotebookPen,Search,ArrowUpRight,Pencil,Trash2} from 'lucide-vue-next'
import {allPages} from '../api'
import {isBookmarkDeleted} from '../platform/bookmark-cache'
import type {ReadingNote} from '../api/types'
import {useRequestScope} from '../platform/request-scope'
import {useApp} from '../stores/app'
import Sheet from '../components/Sheet.vue'
import NoteEditor from '../components/NoteEditor.vue'
import BookmarkRemoval from '../components/BookmarkRemoval.vue'
const router=useRouter(),store=useApp(),capture=useRequestScope(),notes=ref<ReadingNote[]>([]),query=ref(''),bookFilter=ref(''),loading=ref(true),error=ref(''),editing=ref<ReadingNote|null>(null),removing=ref<ReadingNote|null>(null)
let generation=0
const books=computed(()=>[...new Map(notes.value.map(note=>[note.anchor.bookId,note.bookTitle])).entries()])
const filtered=computed(()=>notes.value.filter(note=>(!bookFilter.value||note.anchor.bookId===bookFilter.value)&&(!query.value.trim()||(note.note+' '+note.bookTitle+' '+note.branchName).toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase()))))
async function load(){const scope=capture(),request=++generation;try{const data=await allPages<ReadingNote>('/notebook');if(scope.valid()&&request===generation){notes.value=data.filter(note=>!isBookmarkDeleted(note.anchor.bookId,note.id));error.value=''}}catch(e){if(scope.valid()&&request===generation)error.value=(e as Error).message}finally{if(scope.valid()&&request===generation)loading.value=false}}
function open(note:ReadingNote){router.push({path:`/books/${note.anchor.bookId}/read`,query:{branch:note.anchor.branchId,revision:note.anchor.revisionId,chapter:note.anchor.chapterId,anchor:JSON.stringify(note.anchor)}})}
function bookmarkRemoved(event:Event){const value=(event as CustomEvent<{bookId:string;bookmarkId:string}>).detail;if(!value)return;generation++;notes.value=notes.value.filter(note=>note.id!==value.bookmarkId||note.anchor.bookId!==value.bookId);void load()}
function removed(event:Event){const id=(event as CustomEvent<{bookId:string}>).detail?.bookId;generation++;notes.value=notes.value.filter(note=>note.anchor.bookId!==id);if(editing.value?.anchor.bookId===id)editing.value=null;if(removing.value?.anchor.bookId===id)removing.value=null;if(bookFilter.value===id)bookFilter.value='';void load()}
onMounted(()=>{void load();window.addEventListener('reader-book-deleted',removed);window.addEventListener('reader-bookmark-deleted',bookmarkRemoved)});onUnmounted(()=>{generation++;window.removeEventListener('reader-book-deleted',removed);window.removeEventListener('reader-bookmark-deleted',bookmarkRemoved)})
</script>
<template><div class="page-heading row between"><div><span class="eyebrow">留下想法 · 留住故事</span><h1>阅读笔记</h1><p>故事之外的几行字，都是你的阅读轨迹。</p></div><RouterLink to="/insights" class="inline-link">查看阅读记录<ArrowUpRight :size="18"/></RouterLink></div><div class="collection-tools"><label class="search-field"><Search :size="18"/><input v-model="query" aria-label="搜索阅读笔记" placeholder="搜索想法、书名或故事线" type="search" maxlength="100"></label><label class="compact-select">来自<select v-model="bookFilter" aria-label="按书籍筛选笔记"><option value="">所有书籍</option><option v-for="[id,title] in books" :key="id" :value="id">{{title}}</option></select></label></div><p v-if="error" class="error" role="alert">{{error}}<button @click="load">重新加载</button></p><div v-if="loading" class="loading">正在翻开笔记…</div><div v-else-if="!notes.length" class="empty library-empty"><span class="empty-mark"><NotebookPen :size="32"/></span><h2>让阅读留下回声</h2><p>阅读时选择一段正文，打开「阅读工具 → 写阅读笔记」。<br>保存的想法会在这里汇集。</p><RouterLink to="/library" class="inline-link">回到书架<ArrowUpRight :size="18"/></RouterLink></div><div v-else-if="!filtered.length" class="empty"><h2>没有找到这条想法</h2><button @click="query='';bookFilter=''">清除筛选</button></div><div v-else class="notes-grid"><article v-for="note in filtered" :key="note.id" class="note-card"><div class="row between"><span class="eyebrow">{{note.bookTitle}}</span><small class="muted">{{note.createdAt?new Date(note.createdAt).toLocaleDateString('zh-CN'):note.status==='pending_sync'?'待同步':''}}</small></div><small v-if="note.status==='conflict_copy'">冲突副本</small><p class="note-copy">{{note.note}}</p><p class="note-location">{{note.branchName}} · {{note.location}}</p><div class="row between"><button class="text-action" @click="open(note)">回到这一段<ArrowUpRight :size="17"/></button><div class="row"><button class="icon-button" aria-label="编辑笔记" @click="editing=note"><Pencil :size="18"/></button><button class="icon-button danger" :disabled="!store.online" aria-label="删除笔记" @click="removing=note"><Trash2 :size="18"/></button></div></div></article></div><Sheet v-if="editing" title="编辑阅读笔记" @close="editing=null"><NoteEditor :key="editing.id" :anchor="editing.anchor" :note="editing" @saved="editing=null;load()"/></Sheet><Sheet v-if="removing" title="删除这条笔记？" @close="removing=null"><BookmarkRemoval :key="removing.anchor.bookId+':'+removing.id" :note="removing" @cancel="removing=null" @deleted="removing=null;load()"/></Sheet></template>
